1	import React from 'react';
2	import { DinoCard } from '../../../../molecule/DinoCard/DinoCard';
3	import { EvoAvatar } from '../../../../molecule/EvoAvatar/EvoAvatar';
4	import { rutGonTime } from '../../../../../core/rutGonTime';
5	import { calcDinoCost } from '../../../../../core/calcDinoCost';
6	import { X, ArrowLeft } from 'lucide-react';
7	import type { GachaResultWorkerProps } from '../../types';
8	import './GachaResultWorker.css';
9	
10	const getImage = (lookup: any, category: string, key: string, fallback: string) => {
11	    return lookup?.[category]?.[key] ?? fallback;
12	};
13	
14	/**
15	 * Worker: GachaResultWorker
16	 * Responsibility: Displays the hatched dino specimen, the focused evolution bridge
17	 * showing [Highest Owned Evo] ➔ [Projected Achieved Evo], with pure intermediate
18	 * mini avatars embedded seamlessly in the conduit without text noise or extra sections.
19	 *
20	 * Flow Control:
21	 * - "Back to Gacha" (or Close 'X') dismisses the result window back to the Init Gacha UI.
22	 * - The unbought dino remains saved as "Due" in the background.
23	 * - "Skip Specimen" is accessible exclusively when God Mode (Free Buy Cheat) is active.
24	 */
25	export const GachaResultWorker: React.FC<GachaResultWorkerProps> = ({
26	    resultUuid,
27	    objects,
28	    lookup,
29	    userProgress,
30	    rolledMultiplier = 1,
31	    isBuying,
32	    isSkipping,
33	    isFreeBuyCheat = false,
34	    onBuy,
35	    onCloseToInit,
36	    onGodModeSkip
37	}) => {
38	    const dino = objects.find(o => (o.uuid || o.id || o.name) === resultUuid);
39	    if (!dino) return <div className="text-red-400 text-center py-8">Dino specimen data not found</div>;
40	
41	    const userDinoData = userProgress.owned_dinos?.[resultUuid] || { number: 0, rank: 0 };
42	    const currentRank = Number(userDinoData.rank) || 0;
43	    const currentNumber = Number(userDinoData.number) || 0;
44	
45	    const evolutions = dino.evolutions || [];
46	    const maxCapacity = Number(dino.maximum_number || Math.pow(2, Math.max(0, evolutions.length - 1)));
47	    const remainingToCap = Math.max(1, maxCapacity - currentNumber);
48	
49	    // Clamped buy quantity: cannot exceed evolution requirement
50	    const effectiveQuantity = Math.min(rolledMultiplier, remainingToCap);
51	    const isClamped = rolledMultiplier > effectiveQuantity;
52	
53	    // Projected evolution rank achieved from this purchase
54	    const projectedCount = currentNumber + effectiveQuantity;
55	    const projectedRank = 1 + Math.floor(Math.log2(projectedCount));
56	
57	    // Highest Owned Evo index (0 if unowned) vs Achieved Target index
58	    const highestOwnedIndex = Math.max(0, currentRank - 1);
59	    const achievedTargetIndex = Math.min(Math.max(0, projectedRank - 1), Math.max(0, evolutions.length - 1));
60	
61	    const highestOwnedEvo = currentRank > 0 ? evolutions[highestOwnedIndex] : null;
62	    const achievedTargetEvo = evolutions[achievedTargetIndex];
63	
64	    // Compute intermediate skipped evolution tiers
65	    const startEvoRank = currentRank > 0 ? currentRank : 0;
66	    const intermediateEvos: Array<{ rank: number; level: number; evo: any }> = [];
67	    for (let r = startEvoRank + 1; r < projectedRank; r++) {
68	        const evoObj = evolutions[r - 1];
69	        if (evoObj) {
70	            intermediateEvos.push({
71	                rank: r,
72	                level: evoObj.level || r * 10,
73	                evo: evoObj,
74	            });
75	        }
76	    }
77	
78	    const frameUrl = getImage(lookup, 'portrait_frames', dino.rarity, `https://cdn.paleo.gg/games/jwtg/images/portrait-frame/${dino.rarity}.png`);
79	    const classIconUrl = getImage(lookup, 'class_icons', dino.class || '', `https://cdn.paleo.gg/games/jwtg/images/class/${dino.class}.png`);
80	    const bgKey = `${dino.hybrid_type}_${dino.rarity}`;
81	    const cardBgUrl = getImage(lookup, 'card_backgrounds', bgKey, `https://cdn.paleo.gg/games/jwtg/images/card-bg/${dino.hybrid_type}/${dino.rarity}.png`);
82	
83	    let baseDamage = 0;
84	    let baseHealth = 0;
85	    if (currentRank > 0 && evolutions.length > 0) {
86	        const baseEvo = evolutions.find((e: any) => e.level === currentRank * 10) || evolutions[highestOwnedIndex];
87	        if (baseEvo) {
88	            baseDamage = baseEvo.damage || 0;
89	            baseHealth = baseEvo.health || 0;
90	        }
91	    }
92	    const baseFerocity = Math.floor(baseDamage + (baseHealth / 3.2));
93	
94	    const targetDamage = achievedTargetEvo?.damage || 0;
95	    const targetHealth = achievedTargetEvo?.health || 0;
96	    const targetFerocity = Math.floor(targetDamage + (targetHealth / 3.2));
97	
98	    // Dynamic formula cost scaled by effective quantity
99	    const unitCost = calcDinoCost(dino);
100	    const totalTimeSeconds = unitCost.timeSeconds * effectiveQuantity;
101	    const totalTimeMinutes = Number((unitCost.timeMinutes * effectiveQuantity).toFixed(2));
102	    const totalDnaCost = unitCost.dnaCost * effectiveQuantity;
103	    const totalRedOrbCost = unitCost.redOrbCost * effectiveQuantity;
104	
105	    const hatchTimeFormatted = rutGonTime(totalTimeSeconds, "seconds");
106	
107	    const timeIconUrl = getImage(lookup, 'hybrid_types', 'speed', 'https://cdn.paleo.gg/games/jwtg/images/stats/speed.png');
108	    const dnaIconUrl = 'https://cdn.paleo.gg/games/jwtg/images/resource/dna.png';
109	    const orbIconUrl = getImage(lookup, 'hybrid_types', 'super-hybrid', '');
110	
111	    const rarityMap: Record<string, string> = {
112	        tournament: "legendary",
113	        vip: "legendary",
114	        star: "legendary",
115	        toy: "legendary",
116	        "super-star": "legendary"
117	    };
118	    const displayRarity = (rarityMap[dino.rarity?.toLowerCase()] || dino.rarity || "").toUpperCase();
119	
120	    const damageIcon = getImage(lookup, 'stats', 'damage', 'https://cdn.paleo.gg/games/jwtg/images/stats/damage.png');
121	    const healthIcon = getImage(lookup, 'stats', 'health', 'https://cdn.paleo.gg/games/jwtg/images/stats/health.png');
122	    const feroIcon = getImage(lookup, 'stats', 'ferocity', 'https://cdn.paleo.gg/games/jwtg/images/stats/ferocity.png');
123	
124	    return (
125	        <div className="dino-gacha-result relative">
126	            {/* Top Close / Back to Gacha Dismiss Button */}
127	            <button
128	                type="button"
129	                onClick={onCloseToInit}
130	                className="absolute -top-3 right-0 md:-right-2 z-50 p-2 rounded-xl bg-black/60 hover:bg-white/10 text-gray-400 hover:text-white border border-white/15 transition cursor-pointer flex items-center gap-1.5 text-xs font-mono select-none shadow-md"
131	                title="Return to Gacha View (Dino stays due until purchased)"
132	            >
133	                <ArrowLeft className="w-3.5 h-3.5 text-[#ffd86b]" />
