def get_thresholds(evo_count):
    thresholds = []
    for e in range(1, evo_count + 1):
        if e <= 4:
            thresholds.append(2 ** (e - 1))
        else:
            thresholds.append(8 + (e - 4) * 4)
    return thresholds

def calc_rank(count, evo_count):
    if count <= 0: return 0
    thresh = get_thresholds(evo_count)
    rank = 0
    for i, t in enumerate(thresh):
        if count >= t:
            rank = i + 1
        else:
            break
    return rank

print('4-evo thresholds:', get_thresholds(4))
print('10-evo thresholds:', get_thresholds(10))
print('4-evo ranks for counts [0, 1, 2, 3, 4, 7, 8, 9]:', [(c, calc_rank(c, 4)) for c in [0, 1, 2, 3, 4, 7, 8, 9]])
