1	import React, { useMemo, useState } from 'react';
2	import { rutGonTime } from '../../../core/rutGonTime';
3	import { calcDinoMaxCapacity } from '../../../core/evolutionEngine';
4	import { EvoAvatar } from '../../molecule/EvoAvatar/EvoAvatar';
5	
6	interface AllDinosTabProps {
7	    objects: any[];
8	    lookup: any;
9	    userProgress: any;
10	    onSelectDino: (uuid: string) => void;
11	}
12	
13	export const AllDinosTab: React.FC<AllDinosTabProps> = ({
14	    objects,
15	    lookup,
16	    userProgress,
17	    onSelectDino
18	}) => {
19	    const [searchTerm, setSearchTerm] = useState('');
20	    const [filterClasses, setFilterClasses] = useState<string[]>([]);
21	    const [filterRarities, setFilterRarities] = useState<string[]>([]);
22	    const [sortBy, setSortBy] = useState<string>('ferocity');
23	    const [sortOrder, setSortOrder] = useState<'desc' | 'asc'>('desc');
24	
25	    const getImage = (category: string, key: string, fallback: string) => {
26	        return lookup?.[category]?.[key] ?? fallback;
27	    };
28	
29	    const uniqueClasses = useMemo(() => Array.from(new Set(objects.map(o => (o.class || '').toLowerCase()))).filter(Boolean), [objects]);
30	    const uniqueRarities = useMemo(() => Array.from(new Set(objects.map(o => (o.rarity || '').toLowerCase()))).filter(Boolean), [objects]);
31	
32	    const toggleFilter = (item: string, list: string[], setList: React.Dispatch<React.SetStateAction<string[]>>) => {
33	        if (list.includes(item)) setList(list.filter(i => i !== item));
34	        else setList([...list, item]);
35	    };
36	
37	    const listData = useMemo(() => {
38	        if (!objects || !Array.isArray(objects)) return [];
39	
40	        let mapped = objects.map(item => {
41	            const uuid = item.uuid || item.id || item.name;
42	            const userDino = userProgress?.owned_dinos?.[uuid];
43	
44	            const number = userDino ? (Number(userDino.number) || 0) : 0;
45	            const rank = userDino ? (Number(userDino.rank) || 0) : 0;
46	            const isUnlocked = number > 0;
47	
48	            const evolutions = item.evolutions || [];
49	            const maxIndex = Math.max(0, evolutions.length - 1);
50	            const targetRank = Math.max(1, rank);
51	            let evoIndex = targetRank - 1;
52	            if (evoIndex > maxIndex) evoIndex = maxIndex;
53	
54	            const currentEvo = evolutions[evoIndex] || {};
55	
56	            const damage = currentEvo.damage || 0;
57	            const health = currentEvo.health || 0;
58	            const ferocity = damage + (health / 3.2);
59	            const hatchTime = Number(item.hatch_time_mins) || 0;
60	
61	            const sellPrice = (Number(item.sell_price_dna) || 0) * 2;
62	            const efficiency = (sellPrice > 0 && hatchTime > 0) ? (ferocity / (sellPrice * hatchTime)) : 0;
63	            const releaseTime = new Date(item.release_date || "1970-01-01").getTime();
64	
65	            const maximumNumber = calcDinoMaxCapacity(item);
66	
67	            return {
68	                uuid, isUnlocked, number, rank, maximumNumber, ferocity, damage, health, hatchTime, sellPrice, efficiency, releaseTime,
69	                evoImg: currentEvo.image_url || "",
70	                rarity: (item.rarity || "").toLowerCase(),
71	                class: (item.class || "").toLowerCase(),
72	                name: item.name || "",
73	                image_url: item.image_url || "",
74	                hybrid_type: item.hybrid_type || "",
75	                region: item.region || "",
76	                facts: item.facts || [],
77	                ingredients: item.ingredients || [],
78	                evolutions: item.evolutions || []
79	            };
80	        });
81	
82	        // Filter by search
83	        if (searchTerm.trim() !== '') {
84	            const term = searchTerm.toLowerCase().trim();
85	            mapped = mapped.filter(d =>
86	                d.name.toLowerCase().includes(term) ||
87	                d.class.includes(term) ||
88	                d.rarity.includes(term) ||
89	                d.hybrid_type.includes(term) ||
90	                d.region.includes(term)
91	            );
92	        }
93	
94	        // Filter by class
95	        if (filterClasses.length > 0) {
96	            mapped = mapped.filter(d => filterClasses.includes(d.class));
97	        }
98	        // Filter by rarity
99	        if (filterRarities.length > 0) {
100	            mapped = mapped.filter(d => filterRarities.includes(d.rarity));
101	        }
102	
103	        // Sort
104	        mapped.sort((a, b) => {
105	            if (a.isUnlocked && !b.isUnlocked) return -1;
106	            if (!a.isUnlocked && b.isUnlocked) return 1;
107	
108	            const valA = (a as any)[sortBy] || 0;
109	            const valB = (b as any)[sortBy] || 0;
110	            const modifier = sortOrder === 'asc' ? 1 : -1;
111	
112	            if (valA !== valB) {
113	                return (valA - valB) * modifier;
114	            }
115	
116	            return b.releaseTime - a.releaseTime;
117	        });
118	
119	        return mapped;
120	    }, [objects, userProgress, searchTerm, filterClasses, filterRarities, sortBy, sortOrder]);
121	
122	    const getStatDisplayInfo = (data: any) => {
123	        switch (sortBy) {
124	            case 'damage':
125	                return {
126	                    valueStr: Math.round(data.damage).toLocaleString(),
127	                    icon: getImage("stats", "damage", "https://cdn.paleo.gg/games/jwtg/images/stats/damage.png"),
128	                    color: "#e74c3c"
129	                };
130	            case 'health':
131	                return {
132	                    valueStr: Math.round(data.health).toLocaleString(),
133	                    icon: getImage("stats", "health", "https://cdn.paleo.gg/games/jwtg/images/stats/health.png"),
134	                    color: "#2ecc71"
135	                };
136	            case 'hatchTime':
137	                return {
138	                    valueStr: rutGonTime(data.hatchTime, 'minutes'),
139	                    icon: getImage("stats", "time", "⏳"),
140	                    color: "#3498db"
141	                };
142	            case 'sellPrice':
143	                return {
144	                    valueStr: Math.round(data.sellPrice).toLocaleString(),
145	                    icon: getImage("stats", "dna", "🧬"),
146	                    color: "#9b59b6"
147	                };
148	            case 'efficiency':
149	                return {
150	                    valueStr: data.efficiency.toFixed(4),
151	                    icon: getImage("stats", "efficiency", "📈"),
152	                    color: "#00e5ff"
