// 3. Compute dynamic weights:
// Base weight from ferocity (inverse ferocity principle):
// normal_chance_with_that_ferocity = 1 / max(1, ferocity)
// Manager's Hybrid scaling formula:
// hybrid_weight = normal_weight * total_materials_owned / 4 (with low baseline floor for 0 materials)
let totalInverseWeight = 0;
const candidates = eligibleList.map(({ dino, uuid, evolutions, evo4, baseEvo4Fero }) => {
    const rawIngredients: any[] = Array.isArray(dino.ingredients) ? dino.ingredients : [];
    let ownedIngredientsCount = 0;
    const ingredientUuids: string[] = [];

    for (const ing of rawIngredients) {
        const ingUuid = typeof ing === 'string' ? ing : (ing?.uuid || ing?.id || ing?.name);
        if (ingUuid) {
            ingredientUuids.push(ingUuid);
            ownedIngredientsCount += Number(ownedDinos[ingUuid]?.number || 0);
        }
    }

    const hybridType = String(dino.hybrid_type || '').toLowerCase();
    const hasIngredients = (hybridType === 'hybrid' || hybridType === 'super-hybrid') && ingredientUuids.length > 0;

    // Baseline inverse ferocity weight
    const baseWeight = 1 / Math.max(1, baseEvo4Fero);

    // Manager's Hybrid scaling: normal_chance * materials / 4
    let rawWeight = baseWeight;
    let hybridMultiplier = 1;
    if (hasIngredients) {
        hybridMultiplier = Math.max(0.2, ownedIngredientsCount) / 4;
        rawWeight = baseWeight * hybridMultiplier;
    }

    totalInverseWeight += rawWeight;

    const userDinoData = ownedDinos[uuid] || { number: 0, rank: 0 };
    const ownedCount = Number(userDinoData.number || 0);
    const currentRank = calcDinoRank(ownedCount, evolutions.length);
    const maximumNumber = calcDinoMaxCapacity(dino);
    const maxEvo = evolutions[evolutions.length - 1] || evo4;

    const cost = calcDinoCost(dino);

    return {
        uuid,
        name: dino.name || '',
        rarity: String(dino.rarity || '').toLowerCase(),
        class: dino.class,
        hybrid_type: dino.hybrid_type,
        ferocity: baseEvo4Fero,
        modifiedFerocity: baseEvo4Fero,
        hybridMultiplier,
        rawWeight,
        dropRatePercent: 0,
        maxDamage: Number(maxEvo.damage || 0),
        maxHealth: Number(maxEvo.health || 0),
        maxEvoImg: maxEvo.image_url || dino.image_url,
        evo1Img: evolutions[0]?.image_url || dino.image_url,
        isOwned: ownedCount > 0,
        ownedCount,
        currentRank,
        maximumNumber,
        image_url: dino.image_url,
        hatch_time_mins: dino.hatch_time_mins,
        buy_price_dna: dino.buy_price_dna,
        sell_price_dna: dino.sell_price_dna,
        ingredients: ingredientUuids,
        ownedIngredientsCount,
        totalIngredientsCount: ingredientUuids.length,
        cost,
    };
});

// 4. Calculate percentage drop rates:
for (const item of candidates) {
    item.dropRatePercent = totalInverseWeight > 0
        ? (item.rawWeight / totalInverseWeight) * 100
        : 100 / candidates.length;
}

