// Base weight from ferocity (inverse ferocity principle):
// normal_chance_with_that_ferocity = 1 / max(1, ferocity)
// Manager's Hybrid scaling formula:
// hybrid_weight = normal_weight * total_materials_owned / 4 (with low baseline floor for 0 materials)
let totalInverseWeight = 0;
const candidates = eligibleList.map(({ dino, uuid, evolutions, evo4, baseEvo4Fero }) => {
    const rawIngredients: any[] = Array.isArray(dino.ingredients) ? dino.ingredients : [];
    let ownedIngredientsCount = 0;
    const ingredientUuids: string[] = [];

    for (const ing of rawIngredients) {
        const ingUuid = typeof ing === 'string' ? ing : (ing?.uuid || ing?.id || ing?.name);
        if (ingUuid) {
            ingredientUuids.push(ingUuid);
            ownedIngredientsCount += Number(ownedDinos[ingUuid]?.number || 0);
        }
    }

    const hybridType = String(dino.hybrid_type || '').toLowerCase();
    const hasIngredients = (hybridType === 'hybrid' || hybridType === 'super-hybrid') && ingredientUuids.length > 0;

    // Baseline inverse ferocity weight
    const baseWeight = 1 / Math.max(1, baseEvo4Fero);

    // Manager's Hybrid scaling: normal_chance * materials / 4
    let rawWeight = baseWeight;
    let hybridMultiplier = 1;
    if (hasIngredients) {
        hybridMultiplier = Math.max(0.2, ownedIngredientsCount) / 4;
        rawWeight = baseWeight * hybridMultiplier;
    }

