    const userDinoData = ownedDinos[uuid] || { number: 0, rank: 0 };
    const ownedCount = Number(userDinoData.number || 0);
    const currentRank = calcDinoRank(ownedCount, evolutions.length);
    const maximumNumber = calcDinoMaxCapacity(dino);
    const maxEvo = evolutions[evolutions.length - 1] || evo4;

