/* ============================================================================ */
/* GACHA RESULT WORKER STYLES                                                  */
/* Focused Evolution Bridge (Pure Visual Nodes + Inline Center Minis)          */
/* ============================================================================ */

.dino-gacha-result {
    display: grid;
    grid-template-columns: minmax(280px, 1.05fr) minmax(320px, 1.15fr);
    align-items: center;
    justify-content: center;
    gap: 28px;
    width: 100%;
    max-width: 860px;
    animation: dinoResultFadeIn 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    margin: 0 auto;
}

@keyframes dinoResultFadeIn {
    from { opacity: 0; transform: translateY(12px) scale(0.98); }
    to { opacity: 1; transform: translateY(0) scale(1); }
}

@media (max-width: 860px) {
    .dino-gacha-result {
        grid-template-columns: 1fr;
        justify-items: center;
        gap: 20px;
    }
}

.dino-gacha-left-card {
    display: flex;
    justify-content: center;
    align-items: center;
    transform: scale(1.05);
    transform-origin: center center;
}

.dino-gacha-right-panel {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    width: 100%;
    max-width: 360px;
}

/* FOCUSED EVOLUTION BRIDGE CONTAINER */
.dino-evo-bridge {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    width: 100%;
    padding: 12px 16px;
    border-radius: 16px;
    background: linear-gradient(145deg, rgba(22, 17, 30, 0.95), rgba(10, 8, 14, 0.98));
    border: 1.5px solid rgba(255, 215, 0, 0.3);
    box-shadow: 0 10px 28px rgba(0, 0, 0, 0.45);
    user-select: none;
    box-sizing: border-box;
}

.dino-evo-node {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    flex-shrink: 0;
}

.dino-evo-avatar-box {
    position: relative;
    border-radius: 14px;
    padding: 3px;
    background: #111;
    border: 2px solid rgba(255, 255, 255, 0.15);
    transition: all 0.2s ease-out;
}

.dino-evo-avatar-box.is-owned-node {
    border-color: #00e5ff;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.5), 0 0 14px rgba(0, 229, 255, 0.35);
}

.dino-evo-avatar-box.is-target-node {
    border-color: #ffd700;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.5), 0 0 18px rgba(255, 215, 0, 0.6);
    animation: evoTargetGlow 2s infinite alternate ease-in-out;
}

@keyframes evoTargetGlow {
    from {
        box-shadow: 0 4px 14px rgba(0, 0, 0, 0.5), 0 0 12px rgba(255, 215, 0, 0.4);
        border-color: #ffd700;
    }
    to {
        box-shadow: 0 4px 20px rgba(0, 0, 0, 0.6), 0 0 24px rgba(255, 215, 0, 0.85), inset 0 0 10px rgba(255, 215, 0, 0.2);
        border-color: #ffffff;
    }
}

.dino-evo-node-title {
    font-size: 9.5px;
    font-weight: 700;
    font-family: monospace;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: #8c7a9e;
}

.dino-evo-node-rank {
    font-size: 12px;
    font-weight: 900;
    font-family: monospace;
    letter-spacing: 0.5px;
}

.dino-evo-node-rank.owned-rank {
    color: #00e5ff;
}

.dino-evo-node-rank.target-rank {
    color: #ffd700;
    text-shadow: 0 0 10px rgba(255, 215, 0, 0.7);
}

/* SHORT & SLEEK CENTER CONNECTOR */
.dino-evo-connector {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 5px;
    flex-shrink: 0;
}

.dino-evo-connector-badge {
    font-size: 9px;
    font-weight: 900;
    font-family: monospace;
    color: #ffd700;
    background: rgba(255, 215, 0, 0.18);
    border: 1px solid rgba(255, 215, 0, 0.4);
    padding: 2px 7px;
    border-radius: 6px;
    white-space: nowrap;
}

.dino-evo-connector-arrow {
    display: flex;
    align-items: center;
    gap: 2px;
    color: #ffd700;
    filter: drop-shadow(0 0 8px rgba(255, 215, 0, 0.6));
}

.dino-evo-connector-line {
    width: 28px;
    height: 3px;
    border-radius: 2px;
    background: linear-gradient(90deg, #00e5ff, #ffd700);
}

.dino-evo-arrow-head {
    font-size: 11px;
    line-height: 1;
}

/* PURE MINI AVATAR ROW UNDERNEATH ARROW */
.dino-evo-mini-row {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    margin-top: 2px;
}

.dino-evo-mini-box {
    position: relative;
    border-radius: 8px;
    background: #111;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1.5px;
    border: 1px solid rgba(255, 215, 0, 0.45);
    box-shadow: 0 0 6px rgba(255, 215, 0, 0.35);
    transition: transform 0.15s ease, border-color 0.15s ease;
}

.dino-evo-mini-box:hover {
    transform: scale(1.15);
    border-color: #ffd700;
    box-shadow: 0 0 10px rgba(255, 215, 0, 0.7);
}

/* GAMBLE RESOLUTION BANNER */
.dino-gamble-resolution {
    width: 100%;
    padding: 8px 12px;
    border-radius: 12px;
    background: linear-gradient(135deg, rgba(25, 18, 36, 0.95), rgba(10, 8, 14, 0.98));
    border: 1px solid rgba(255, 215, 0, 0.25);
    display: flex;
    flex-direction: column;
    gap: 3px;
    text-align: center;
}

.dino-gamble-title {
    font-size: 11.5px;
    font-weight: 800;
    color: #ffd700;
    font-family: monospace;
}

.dino-gamble-sub {
    font-size: 10px;
    color: #8c7a9e;
}

/* STATS CARD */
.dino-gacha-stats-card {
    width: 100%;
    padding: 10px;
    box-sizing: border-box;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 12px;
    background: linear-gradient(145deg, rgba(255, 255, 255, 0.06), rgba(0, 0, 0, 0.18));
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
    text-align: center;
}

.dino-gacha-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 6px;
}

.dino-gacha-stat {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 2px;
    padding: 5px 3px;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.05);
}

.dino-gacha-stat-icon {
    width: 16px;
    height: 16px;
    object-fit: contain;
}

.dino-gacha-stat-label {
    font-size: 8.5px;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    opacity: 0.6;
}

.dino-stat-flicker {
    color: #ffd700;
    margin-left: 3px;
    font-size: 11px;
    font-weight: 800;
}

.dino-gacha-costs {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    width: 100%;
}

.dino-gacha-cost {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 2px;
    padding: 6px 8px;
    border-radius: 9px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.08);
    flex: 1;
}

.dino-gacha-cost-label {
    font-size: 8.5px;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    opacity: 0.6;
}

.dino-gacha-cost-value {
    font-size: 12px;
    font-weight: 700;
    white-space: nowrap;
}

.dino-buy-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
    min-height: 52px;
    border: 1px solid rgba(56, 189, 248, 0.4);
    border-radius: 12px;
    padding: 8px 16px;
    font-size: 14.5px;
    font-weight: 800;
    color: white;
    background: linear-gradient(135deg, #0369a1 0%, #0284c7 50%, #38bdf8 100%);
    box-shadow: 0 6px 20px rgba(2, 132, 199, 0.35);
    transition: transform 0.08s ease-out, box-shadow 0.08s ease-out, opacity 0.15s ease;
    cursor: pointer;
    user-select: none;
}

.dino-buy-button:hover:not(:disabled) {
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(56, 189, 248, 0.5);
}

.dino-buy-button:active:not(:disabled) {
    transform: scale(0.98);
}

.dino-pass-button {
    width: 100%;
    padding: 9px 16px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.15);
    color: #cbd5e1;
    font-size: 12.5px;
    font-weight: bold;
    cursor: pointer;
    transition: background-color 0.1s ease, border-color 0.1s ease, transform 0.08s ease;
    user-select: none;
}

.dino-pass-button:hover:not(:disabled) {
    background: rgba(255, 255, 255, 0.1);
    border-color: rgba(255, 255, 255, 0.3);
    color: #ffffff;
    transform: translateY(-1px);
}

.dino-pass-button:active:not(:disabled) {
    transform: scale(0.98);
}

.dino-pass-button.is-due-locked {
    background: rgba(20, 15, 25, 0.6);
    border: 1px dashed rgba(255, 255, 255, 0.15);
    color: #64748b;
    cursor: not-allowed;
    opacity: 0.75;
}

.dino-pass-button.is-due-locked:hover {
    background: rgba(20, 15, 25, 0.6);
    border-color: rgba(255, 255, 255, 0.15);
    color: #64748b;
    transform: none;
}

