    // Dispatcher: Step 2 -> Step 3 (Animation finished -> Persist as Due Dino & Show Result)
    const handleAnimationComplete = async () => {
        if (pendingUuid) {
            const newDue: DueDinoData = {
                uuid: pendingUuid,
                multiplier: rolledMultiplier
            };
            if (onSetDueDino) {
                onSetDueDino(newDue);

