python -c "
import json

with open('universe-25/src/apps/arc-jurassic/data/dino.json', 'r', encoding='utf-8') as f:
    dinos = json.load(f)

# Build a map of ingredient pairings
# For each ingredient dino uuid -> set of partner dino uuids that combine with it
partner_map = {} # { ing_uuid: set of partner_uuids }

for k, v in dinos.items():
    ings = v.get('ingredients', [])
    if len(ings) >= 2:
        ing_uuids = []
        for ing in ings:
            u = ing if isinstance(ing, str) else (ing.get('uuid') or ing.get('id') or ing.get('name'))
            if u:
                ing_uuids.append(u)

        for i, u1 in enumerate(ing_uuids):
            for j, u2 in enumerate(ing_uuids):
                if i != j:
                    if u1 not in partner_map: partner_map[u1] = set()
                    partner_map[u1].add(u2)

print('Sample partner mappings:')
for sample_k in ['alanqa', 'diplocaulus', 'tropeognathus', 'bonitasaura', 'triceratops']:
    partners = partner_map.get(sample_k, set())
    partner_names = [dinos.get(p, {}).get('name', p) for p in partners]
    print(f'{sample_k} ({dinos.get(sample_k, {}).get(\"name\")}) partners -> {partner_names}')
"

