// 1. Identify creatures exceeding max limit & track owned species
const ownedSpeciesSet = new Set<string>();
for (const dino of objects) {
    const uuid = dino.uuid || dino.id || dino.name;
    const maxLimit = calcDinoMaxCapacity(dino);
    const userCount = Number(ownedDinos[uuid]?.number || 0);

    if (userCount >= maxLimit) {
        excludedIdsSet.add(uuid);
    }
    if (userCount > 0) {
        ownedSpeciesSet.add(uuid);
    }
}

// 2. Discover partner ingredients unlocked by owned species across all hybrid recipes
const partnerUnlockedUuids = new Set<string>();
for (const dino of objects) {
    const rawIngredients: any[] = Array.isArray(dino.ingredients) ? dino.ingredients : [];
    if (rawIngredients.length >= 2) {
        const ingredientUuids: string[] = [];
        for (const ing of rawIngredients) {
            const ingUuid = typeof ing === 'string' ? ing : (ing?.uuid || ing?.id || ing?.name);
            if (ingUuid) ingredientUuids.push(ingUuid);
        }

        // If player owns at least one ingredient species for this hybrid recipe
        if (ingredientUuids.some(u => ownedSpeciesSet.has(u))) {
            // All partner ingredients for this hybrid recipe bypass the cap!
            for (const u of ingredientUuids) {
                partnerUnlockedUuids.add(u);
            }
        }
    }
}

