const excludedIdsSet = new Set<string>(manualExcludedIds);

// 1. Identify creatures exceeding max limit & track owned species
const ownedSpeciesSet = new Set<string>();
for (const dino of objects) {
    const uuid = dino.uuid || dino.id || dino.name;
    const maxLimit = calcDinoMaxCapacity(dino);
    const userCount = Number(ownedDinos[uuid]?.number || 0);

    if (userCount >= maxLimit) {
        excludedIdsSet.add(uuid);
    }
    if (userCount > 0) {
        ownedSpeciesSet.add(uuid);
    }
}

// 2. Discover partner ingredients unlocked by owned species across all hybrid recipes
const partnerUnlockedUuids = new Set<string>();
for (const dino of objects) {
    const rawIngredients: any[] = Array.isArray(dino.ingredients) ? dino.ingredients : [];
    if (rawIngredients.length >= 2) {
        const ingredientUuids: string[] = [];
        for (const ing of rawIngredients) {
            const ingUuid = typeof ing === 'string' ? ing : (ing?.uuid || ing?.id || ing?.name);
            if (ingUuid) ingredientUuids.push(ingUuid);
        }

        // If player owns at least one ingredient species for this hybrid recipe
        if (ingredientUuids.some(u => ownedSpeciesSet.has(u))) {
            // All partner ingredients for this hybrid recipe bypass the cap!
            for (const u of ingredientUuids) {
                partnerUnlockedUuids.add(u);
            }
        }
    }
}

// 3. Filter eligible creatures & search for Next Unlock Milestone
const eligibleList: any[] = [];
const lockedAboveCapList: any[] = [];

for (const dino of objects) {
    const uuid = dino.uuid || dino.id || dino.name;
    if (excludedIdsSet.has(uuid)) continue;

    const evolutions = dino.evolutions || [];
    if (evolutions.length === 0) continue;

    const evo4 = evolutions[3] || evolutions[evolutions.length - 1];
    const baseEvo4Fero = Number(
        dino.evo4_ferocity ||
        evo4.ferocity ||
        Math.floor(Number(evo4.damage || 0) + (Number(evo4.health || 0) / 3.2))
    );

    const isPartnerUnlock = partnerUnlockedUuids.has(uuid) && baseEvo4Fero > cap;

    if (baseEvo4Fero <= cap || isPartnerUnlock) {
        eligibleList.push({
            dino,
            uuid,
            evolutions,
            evo4,
            baseEvo4Fero,
            isPartnerUnlock,
        });
    } else {
        lockedAboveCapList.push({
            uuid,
            name: dino.name || '',
            rarity: String(dino.rarity || '').toLowerCase(),
            class: dino.class,
            image_url: dino.image_url,
            requiredFerocity: baseEvo4Fero,
            deltaNeeded: Math.max(1, Math.ceil(baseEvo4Fero * 2.5) - top3Ferocity),
        });
    }
}

// Calculate Next Unlock Milestone
lockedAboveCapList.sort((a, b) => a.requiredFerocity - b.requiredFerocity || a.name.localeCompare(b.name));
const nextUnlock: NextUnlockMilestone | null = lockedAboveCapList.length > 0 ? lockedAboveCapList[0] : null;

if (eligibleList.length === 0) {
    return {
        pool: [],
