                                {/* Selected Sort Stat (e.g. Ferocity or other sort metrics) */}
                                <div className="flex items-center justify-center gap-1 text-[11px] font-bold font-mono leading-none mt-0.5" style={{ color: statInfo.color }}>
                                    {statInfo.icon.startsWith('http') ? (
                                        <img src={statInfo.icon} width="11" height="11" className="object-contain" alt={sortBy} />
                                    ) : (
                                        <span className="text-[10px]">{statInfo.icon}</span>
                                    )}
                                    <span>{statInfo.valueStr}</span>
                                </div>
                            </div>
                        ) : (
                            <div className="text-[10px] text-gray-500 mt-1 font-mono">Locked</div>
                        )}
                    </div>
                );
            })}
        </div>
    </div>
);
